import {
  Credentials as AwsCredentials,
  Endpoint as AwsEndpoint,
  Region as AwsRegion,
} from "@distilled.cloud/aws";
import * as BunHttpClient from "@effect/platform-bun/BunHttpClient";
import { AWSEnvironment, makeS3State } from "alchemy/AWS";
import { inMemoryState, State } from "alchemy/State";
import { Config, Effect, Layer, Redacted, Schema } from "effect";
import type { HttpClient } from "effect/unstable/http/HttpClient";

export const AlchemyR2AccountId = Schema.String.pipe(
  Schema.check(Schema.isPattern(/^[a-f0-9]{32}$/)),
  Schema.brand("@bundjil/infrastructure/state/AlchemyR2AccountId")
);
export type AlchemyR2AccountId = typeof AlchemyR2AccountId.Type;
export type AlchemyR2AccountIdEncoded = typeof AlchemyR2AccountId.Encoded;

export const AlchemyR2BucketName = Schema.String.pipe(
  Schema.check(Schema.isPattern(/^[a-z0-9](?:[a-z0-9.-]{1,61}[a-z0-9])$/)),
  Schema.brand("@bundjil/infrastructure/state/AlchemyR2BucketName")
);
export type AlchemyR2BucketName = typeof AlchemyR2BucketName.Type;
export type AlchemyR2BucketNameEncoded = typeof AlchemyR2BucketName.Encoded;

export const AlchemyR2StatePrefix = Schema.String.pipe(
  Schema.check(Schema.isPattern(/^[a-z0-9][a-z0-9/-]*[a-z0-9]$/)),
  Schema.brand("@bundjil/infrastructure/state/AlchemyR2StatePrefix")
);
export type AlchemyR2StatePrefix = typeof AlchemyR2StatePrefix.Type;
export type AlchemyR2StatePrefixEncoded = typeof AlchemyR2StatePrefix.Encoded;

export const AlchemyR2AccessKeyId = Schema.NonEmptyString.pipe(
  Schema.brand("@bundjil/infrastructure/state/AlchemyR2AccessKeyId")
);
export type AlchemyR2AccessKeyId = typeof AlchemyR2AccessKeyId.Type;
export type AlchemyR2AccessKeyIdEncoded = typeof AlchemyR2AccessKeyId.Encoded;

export const AlchemyR2SecretAccessKey = Schema.NonEmptyString.pipe(
  Schema.brand("@bundjil/infrastructure/state/AlchemyR2SecretAccessKey")
);
export type AlchemyR2SecretAccessKey = typeof AlchemyR2SecretAccessKey.Type;
export type AlchemyR2SecretAccessKeyEncoded =
  typeof AlchemyR2SecretAccessKey.Encoded;

export const AlchemyR2StateConfig = Schema.Struct({
  accountId: AlchemyR2AccountId,
  bucketName: AlchemyR2BucketName,
  prefix: AlchemyR2StatePrefix,
  accessKeyId: Schema.Redacted(AlchemyR2AccessKeyId),
  secretAccessKey: Schema.Redacted(AlchemyR2SecretAccessKey),
});
export type AlchemyR2StateConfig = typeof AlchemyR2StateConfig.Type;
export type AlchemyR2StateConfigEncoded = typeof AlchemyR2StateConfig.Encoded;

const accountIdConfig = Config.schema(
  AlchemyR2AccountId,
  "BUNDJIL_ALCHEMY_STATE_ACCOUNT_ID"
).pipe(
  Config.withDefault(
    AlchemyR2AccountId.make("REDACTED")
  )
);

const bucketNameConfig = Config.schema(
  AlchemyR2BucketName,
  "BUNDJIL_ALCHEMY_STATE_BUCKET"
).pipe(Config.withDefault(AlchemyR2BucketName.make("bundjil-alchemy-state")));

const prefixConfig = Config.schema(
  AlchemyR2StatePrefix,
  "BUNDJIL_ALCHEMY_STATE_PREFIX"
).pipe(Config.withDefault(AlchemyR2StatePrefix.make("bundjil/v1")));

const accessKeyIdConfig = Config.schema(
  Schema.Redacted(AlchemyR2AccessKeyId),
  "BUNDJIL_ALCHEMY_STATE_ACCESS_KEY_ID"
);

const secretAccessKeyConfig = Config.schema(
  Schema.Redacted(AlchemyR2SecretAccessKey),
  "BUNDJIL_ALCHEMY_STATE_SECRET_ACCESS_KEY"
);

export const loadAlchemyR2StateConfig = Effect.gen(
  function* loadAlchemyR2StateConfigOperation() {
    return AlchemyR2StateConfig.make({
      accountId: yield* accountIdConfig,
      bucketName: yield* bucketNameConfig,
      prefix: yield* prefixConfig,
      accessKeyId: yield* accessKeyIdConfig,
      secretAccessKey: yield* secretAccessKeyConfig,
    });
  }
).pipe(Effect.withSpan("AlchemyR2StateConfig.load"));

const layerForAlchemyR2StateConfig = (config: AlchemyR2StateConfig) => {
  const endpoint =
    `https://${config.accountId}.r2.cloudflarestorage.com` as const;
  const credentials = AwsCredentials.fromCredentials({
    accessKeyId: Redacted.value(config.accessKeyId),
    secretAccessKey: Redacted.value(config.secretAccessKey),
  });
  const region = Layer.succeed(AwsRegion.Region, Effect.succeed("auto"));
  const providerEndpoint = Layer.succeed(
    AwsEndpoint.Endpoint,
    Effect.succeed(endpoint)
  );
  const environment = Layer.effect(
    AWSEnvironment,
    AwsCredentials.Credentials.pipe(
      Effect.map((credentialEffect) =>
        Effect.succeed({
          accountId: config.accountId,
          region: "auto",
          credentials: credentialEffect,
          endpoint,
        })
      )
    )
  ).pipe(Layer.provide(credentials));
  const dependencies = Layer.mergeAll(
    credentials,
    region,
    providerEndpoint,
    environment,
    BunHttpClient.layer
  );

  return Layer.effect(
    State,
    Effect.gen(function* makeCachedAlchemyR2State() {
      const context = yield* Effect.context<
        | AwsCredentials.Credentials
        | AwsEndpoint.Endpoint
        | AwsRegion.Region
        | AWSEnvironment
        | HttpClient
      >();
      return yield* Effect.cached(
        makeS3State({
          bucketName: config.bucketName,
          prefix: config.prefix,
        }).pipe(Effect.provideContext(context))
      );
    })
  ).pipe(Layer.provide(dependencies));
};

export const layerAlchemyR2State = Layer.unwrap(
  loadAlchemyR2StateConfig.pipe(Effect.map(layerForAlchemyR2StateConfig))
);

export const layerAlchemyR2StateMemory = inMemoryState();
import {
  Array,
  Config,
  Context,
  Effect,
  HashMap,
  Layer,
  Match,
  Option,
  Redacted,
  Schedule,
  Schema,
} from "effect";
import {
  HttpClient,
  HttpClientRequest,
  HttpClientResponse,
} from "effect/unstable/http";

import {
  VercelCredentialError,
  VercelDeploymentsReadError,
  VercelDomainsReadError,
  VercelEnvironmentVariablesReadError,
  VercelMarketplaceBindingsReadError,
  VercelProjectsReadError,
} from "./errors.js";
import type {
  DiscoverVercelProject,
  ObserveVercelDeployment,
  ObserveVercelEnvironmentVariable,
  ObserveVercelMarketplaceBinding,
  ObserveVercelProjectDomain,
} from "./schemas.js";
import {
  ListedVercelDeployments,
  ListedVercelEnvironmentVariables,
  ListedVercelMarketplaceBindings,
  ListedVercelProjectDomains,
  ListedVercelProjects,
  ObserveVercelProject,
  VercelCanonicalDomain,
  VercelDeploymentId,
  VercelDeploymentObservation,
  VercelDeploymentObservationAttributes,
  VercelDeploymentStatus,
  VercelDeploymentTarget,
  VercelEnvironmentTarget,
  VercelEnvironmentVariableAttributes,
  VercelEnvironmentVariableId,
  VercelEnvironmentVariableKey,
  VercelEnvironmentVariableObservation,
  VercelEnvironmentVariableType,
  VercelEnvironmentVariableUpdatedAt,
  VercelGitBranch,
  VercelGitSha,
  VercelIntegrationConfigurationId,
  VercelIntegrationId,
  VercelMarketplaceBindingAttributes,
  VercelMarketplaceBindingObservation,
  VercelMarketplaceDatabaseId,
  VercelMarketplaceResourceId,
  VercelPaginationCursor,
  VercelProjectAttributes,
  VercelProjectDomainAttributes,
  VercelProjectDomainObservation,
  VercelProjectDiscovery,
  VercelProjectId,
  VercelProjectName,
  VercelProjectObservation,
  VercelAccessToken,
  ListVercelDeployments,
  ListVercelEnvironmentVariables,
  ListVercelMarketplaceBindings,
  ListVercelProjectDomains,
  ListVercelProjects,
} from "./schemas.js";
import {
  VercelCredentials,
  VercelDeployments,
  VercelDomains,
  VercelEnvironmentVariables,
  VercelMarketplaceBindings,
  VercelProjects,
} from "./services.js";

const VercelProjectCredentialBinding = Schema.Struct({
  projectId: VercelProjectId,
  accessToken: Schema.RedactedFromValue(Schema.NonEmptyString),
});
const VercelProjectCredentialBindings = Schema.NonEmptyArray(
  VercelProjectCredentialBinding
).pipe(
  Schema.check(
    Schema.makeFilter((bindings) =>
      Array.dedupeWith(
        bindings,
        (left, right) => left.projectId === right.projectId
      ).length === bindings.length
        ? undefined
        : "Vercel project credential bindings must use unique project IDs."
    )
  )
);
const VercelProjectCredentialBindingsJson = Schema.fromJsonString(
  VercelProjectCredentialBindings
);

const vercelAccessTokenConfig = Config.schema(
  VercelAccessToken,
  "VERCEL_INFRASTRUCTURE_ACCESS_TOKEN"
);
const vercelProjectCredentialBindingsConfig = Config.schema(
  VercelProjectCredentialBindingsJson,
  "BUNDJIL_INFRASTRUCTURE_VERCEL_PROJECT_CREDENTIALS_JSON"
);

export const VercelCredentialsLive = Layer.succeed(
  VercelCredentials,
  VercelCredentials.of({
    accessToken: Effect.fn("VercelCredentialsLive.accessToken")(() =>
      vercelAccessTokenConfig.pipe(
        Effect.mapError(
          () =>
            new VercelCredentialError({
              reason: "configurationUnavailable",
            })
        )
      )
    ),
  })
);

export const VercelProjectCredentialsLive = Layer.succeed(
  VercelCredentials,
  VercelCredentials.of({
    accessToken: Effect.fn("VercelProjectCredentialsLive.accessToken")(
      function* (scope) {
        const bindings = yield* vercelProjectCredentialBindingsConfig.pipe(
          Effect.mapError(
            () =>
              new VercelCredentialError({
                reason: "configurationUnavailable",
              })
          )
        );
        const credentialsByProject = HashMap.fromIterable(
          bindings.map((binding) => [binding.projectId, binding.accessToken])
        );
        return yield* Match.value(scope).pipe(
          Match.tag("Team", () =>
            Effect.fail(
