          { concurrency: 1 }
        ).pipe(
          Effect.catchCause(() =>
            Effect.fail(
              new InfrastructureDriftNativeBoundaryError({
                phase: "desiredPlanObservation",
              })
            )
          )
        );
        const native = yield* AlchemySync.plan({
          name: stack.name,
          stage: stack.stage,
        }).pipe(
          Effect.catchCause(() =>
            Effect.fail(
              new InfrastructureDriftNativeBoundaryError({
                phase: "nativeSync",
              })
