name: Infrastructure Drift

on:
  pull_request:
    branches: [main]
  schedule:
    - cron: "17 3 * * 1"
  workflow_dispatch:

permissions:
  contents: read

concurrency:
  group: infrastructure-drift-${{ github.repository }}-${{ github.event.pull_request.number || github.ref }}
  cancel-in-progress: true

jobs:
  preview-report:
    if: github.repository == 'crcorbett/bundjil' && (github.event_name != 'pull_request' || github.event.pull_request.head.repo.full_name == github.repository)
    runs-on: ubuntu-latest
    timeout-minutes: 20
    environment: infrastructure-read-only-preview
    env:
      BUNDJIL_INFRASTRUCTURE_DRIFT_ACCEPT_UNOWNED: "false"
      BUNDJIL_INFRASTRUCTURE_DRIFT_AUTHORITY_PATH: tmp/proof/infrastructure-drift.authority.json
      BUNDJIL_INFRASTRUCTURE_DRIFT_RECEIPT_PATH: tmp/proof/infrastructure-drift.receipt.json
      BUNDJIL_INFRASTRUCTURE_DRIFT_REPORT_PATH: tmp/proof/infrastructure-drift.report.json
      BUNDJIL_INFRASTRUCTURE_DRIFT_RUN_IDENTITY: github-actions:${{ github.repository }}:${{ github.run_id }}:${{ github.run_attempt }}
      BUNDJIL_INFRASTRUCTURE_DRIFT_SOURCE_SHA: ${{ github.event.pull_request.head.sha || github.sha }}
      BUNDJIL_INFRASTRUCTURE_DRIFT_STAGE: preview
      BUNDJIL_INFRASTRUCTURE_MANIFEST_PATH: tmp/proof/infrastructure-drift.manifest.json
      BUNDJIL_INFRASTRUCTURE_MODE: sync
      BUNDJIL_INFRASTRUCTURE_STAGE: preview
    steps:
      - name: Checkout repository
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false

      - name: Setup Node
        uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: "24"

      - name: Setup Bun
        uses: oven-sh/setup-bun@0c5077e51419868618aeaa5fe8019c62421857d6 # v2
        with:
          bun-version: "1.3.14"

      - name: Install dependencies
        run: bun install --frozen-lockfile

      - name: Fetch bounded Preview drift inputs
        id: doppler
        uses: dopplerhq/secrets-fetch-action@451892f16195f9ac360e1a5bcbf0b5fd0e957534 # v2.0.0
        with:
          doppler-token: ${{ secrets.DOPPLER_TOKEN }}

      - name: Prepare bounded read-only custody
        env:
          DRIFT_AUTHORITY_JSON: ${{ steps.doppler.outputs.BUNDJIL_INFRASTRUCTURE_DRIFT_AUTHORITY_JSON }}
          DRIFT_ENV_FILE: ${{ steps.doppler.outputs.BUNDJIL_INFRASTRUCTURE_DRIFT_ENV_FILE }}
          DRIFT_MANIFEST_JSON: ${{ steps.doppler.outputs.BUNDJIL_INFRASTRUCTURE_DRIFT_MANIFEST_JSON }}
        shell: bash
        run: |
          set -euo pipefail
          test -n "$DRIFT_AUTHORITY_JSON"
          test -n "$DRIFT_ENV_FILE"
          test -n "$DRIFT_MANIFEST_JSON"
          umask 077
          mkdir -p tmp/proof
          printf '%s' "$DRIFT_AUTHORITY_JSON" > "$BUNDJIL_INFRASTRUCTURE_DRIFT_AUTHORITY_PATH"
          printf '%s' "$DRIFT_MANIFEST_JSON" > "$BUNDJIL_INFRASTRUCTURE_MANIFEST_PATH"
          printf '%s' "$DRIFT_ENV_FILE" > "$RUNNER_TEMP/bundjil-infrastructure-drift.env"
          chmod 0600 \
            "$BUNDJIL_INFRASTRUCTURE_DRIFT_AUTHORITY_PATH" \
            "$BUNDJIL_INFRASTRUCTURE_MANIFEST_PATH" \
            "$RUNNER_TEMP/bundjil-infrastructure-drift.env"

      - name: Report Preview drift without repair
        run: bun --env-file "$RUNNER_TEMP/bundjil-infrastructure-drift.env" run infrastructure:drift-report:internal
    issues.push(
      finding(
        "AUTH-DRIFT-TRIGGER",
        "Infrastructure drift has one exact pull-request, schedule, and manual read-only signal",
        workflow.path,
        "Restore main pull requests, cron 17 3 * * 1, and workflow_dispatch",
        "The report-only signal set or schedule drifted",
        "Only the three accepted bounded signals start the worker"
      )
    );
  }
  if (
    !/github\.repository\s*==\s*['"]crcorbett\/bundjil['"]/.test(
      workflow.content
    ) ||
    !/github\.event\.pull_request\.head\.repo\.full_name\s*==\s*github\.repository/.test(
      workflow.content
    )
  ) {
    issues.push(
      finding(
        "AUTH-DRIFT-TARGET",
        "Infrastructure drift is exact-repository and same-repository-PR only",
        workflow.path,
        "Restore the exact repository and fork exclusion gates",
        "The repository or fork boundary is absent",
        "Read-only credentials are never exposed to an untrusted fork"
      )
    );
  }
  if (
    !/environment:\s*infrastructure-read-only-preview/.test(workflow.content) ||
    !/BUNDJIL_INFRASTRUCTURE_DRIFT_STAGE:\s*preview/.test(workflow.content) ||
    !/BUNDJIL_INFRASTRUCTURE_STAGE:\s*preview/.test(workflow.content) ||
    /\bprod(?:uction)?\b/i.test(
      workflow.content.replaceAll(
        /BUNDJIL_INFRASTRUCTURE_DRIFT_SOURCE_SHA:[^\n]+/g,
        ""
      )
    )
  ) {
    issues.push(
      finding(
        "AUTH-DRIFT-STAGE",
        "Infrastructure drift is Preview-only and cannot address Production",
        workflow.path,
        "Use only the infrastructure-read-only-preview environment and preview stage",
        "Preview environment/stage is missing or a Production target appears",
        "The report-only worker cannot select Production"
      )
    );
  }
  if (
    secretReferences.length !== expectedSecrets.length ||
    expectedSecrets.some((secret) => !secretReferences.includes(secret))
  ) {
    issues.push(
      finding(
        "AUTH-DRIFT-CUSTODY",
        "Infrastructure drift resolves one config-scoped Doppler token",
        workflow.path,
        "Reference only the environment-scoped DOPPLER_TOKEN secret",
        `Observed secret references: ${secretReferences.join(", ") || "none"}`,
        "Legacy provider values and unrelated secrets do not enter the workflow directly"
      )
    );
  }
  if (
    !/id:\s*doppler\s+uses:\s*dopplerhq\/secrets-fetch-action@451892f16195f9ac360e1a5bcbf0b5fd0e957534\s+# v2\.0\.0\s+with:\s+doppler-token:\s*\$\{\{\s*secrets\.DOPPLER_TOKEN\s*\}\}/.test(
      workflow.content
    ) ||
    !/DRIFT_AUTHORITY_JSON:\s*\$\{\{\s*steps\.doppler\.outputs\.BUNDJIL_INFRASTRUCTURE_DRIFT_AUTHORITY_JSON\s*\}\}/.test(
      workflow.content
    ) ||
    !/DRIFT_ENV_FILE:\s*\$\{\{\s*steps\.doppler\.outputs\.BUNDJIL_INFRASTRUCTURE_DRIFT_ENV_FILE\s*\}\}/.test(
      workflow.content
    ) ||
    !/DRIFT_MANIFEST_JSON:\s*\$\{\{\s*steps\.doppler\.outputs\.BUNDJIL_INFRASTRUCTURE_DRIFT_MANIFEST_JSON\s*\}\}/.test(
      workflow.content
    ) ||
    /inject-env-vars/.test(workflow.content)
  ) {
    issues.push(
      finding(
        "AUTH-DRIFT-DOPPLER",
        "Infrastructure drift fetches once and maps only its three named Doppler outputs",
        workflow.path,
        "Restore the v2.0.0 commit pin, DOPPLER_TOKEN input, three exact output mappings and output-only mode",
        "The Doppler fetch or bounded output mapping drifted",
        "Only the authority, environment and manifest values reach the custody step"
      )
    );
  }
  if (
    !/BUNDJIL_INFRASTRUCTURE_DRIFT_RUN_IDENTITY:\s*github-actions:\$\{\{\s*github\.repository\s*\}\}:\$\{\{\s*github\.run_id\s*\}\}:\$\{\{\s*github\.run_attempt\s*\}\}/.test(
      workflow.content
    )
  ) {
    issues.push(
      finding(
        "AUTH-DRIFT-RUN-IDENTITY",
        "Infrastructure drift binds receipts to the exact GitHub repository, run, and attempt",
        workflow.path,
        "Restore the branded run identity from github.repository, github.run_id, and github.run_attempt",
        "The dynamic GitHub run identity is absent or incomplete",
        "Each report and receipt names its exact hosted execution identity"
      )
    );
  }
  if (
    !/run:\s*bun --env-file [^\n]+ infrastructure:drift-report:internal/.test(
      workflow.content
    ) ||
    /infrastructure:(?:stable-production|[^\\s]*(?:apply|repair|rollback)|photon)|id-token/i.test(
      workflow.content
    )
  ) {
    issues.push(
      finding(
        "AUTH-DRIFT-MUTATION",
        "Infrastructure drift runs only the report boundary and has no repair path",
        workflow.path,
        "Keep only infrastructure:drift-report:internal and remove apply, repair, rollback, Photon, Production, and OIDC paths",
        "The exact report command is absent or a prohibited mutation surface appears",
        "The worker can plan, observe, classify, and report but cannot apply"
      )
    );
  }
  return issues;
};

