class HarnessEvaluationError extends Schema.TaggedErrorClass<HarnessEvaluationError>()(
  "HarnessEvaluationError",
  {
    detail: Schema.NonEmptyString,
    operation: Schema.Literals([
      "decode",
      "discover",
      "encode",
      "read",
      "write",
    ]),
    target: Schema.NonEmptyString,
  }
) {}

const discoverPaths = Effect.tryPromise({
  try: async () => {
    const child = Bun.spawn(
      ["git", "ls-files", "--cached", "--others", "--exclude-standard", "-z"],
      { cwd: repositoryRoot, stderr: "pipe", stdout: "pipe" }
    );
    const [stdout, stderr, exitCode] = await Promise.all([
      new Response(child.stdout).text(),
      new Response(child.stderr).text(),
      child.exited,
    ]);
    if (exitCode !== 0) {
      throw new Error(stderr ?? `git ls-files exited ${exitCode}`);
    }
    return stdout.split("\0").filter(Boolean).toSorted();
  },
  catch: (cause) =>
    new HarnessEvaluationError({
      detail: String(cause),
      operation: "discover",
      target: repositoryRoot,
    }),
});

const read = (path: string) =>
  Effect.tryPromise({
    try: () => Bun.file(resolve(repositoryRoot, path)).text(),
    catch: (cause) =>
      new HarnessEvaluationError({
        detail: String(cause),
        operation: "read",
        target: path,
      }),
  });

const readAtGitCommit = (commit: string, path: string) =>
  Effect.tryPromise({
    try: async () => {
      const child = Bun.spawn(["git", "show", `${commit}:${path}`], {
        cwd: repositoryRoot,
        stderr: "pipe",
        stdout: "pipe",
      });
      const [stdout, stderr, exitCode] = await Promise.all([
        new Response(child.stdout).text(),
        new Response(child.stderr).text(),
        child.exited,
      ]);
      if (exitCode !== 0) {
        throw new Error(stderr || `git show exited ${exitCode}`);
      }
      return stdout;
    },
    catch: (cause) =>
      new HarnessEvaluationError({
        detail: String(cause),
        operation: "read",
        target: `${commit}:${path}`,
      }),
  });

const decode = <A, I>(path: string, schema: Schema.Codec<A, I>) =>
  read(path).pipe(
    Effect.flatMap((content) =>
      Schema.decodeUnknownEffect(schema)(content, {
        onExcessProperty: "error",
      })
    ),
    Effect.mapError(
      (cause) =>
        new HarnessEvaluationError({
          detail: String(cause),
          operation: "decode",
          target: path,
        })
    )
  );

const sha256 = (content: string) =>
  Effect.promise(async () => {
    const digest = await crypto.subtle.digest(
      "SHA-256",
      new TextEncoder().encode(content)
    );
    return [...new Uint8Array(digest)]
      .map((byte) => byte.toString(16).padStart(2, "0"))
      .join("");
  });

