        cwd: repositoryRoot,
        stderr: "pipe",
        stdout: "pipe",
      });
      const [stdout, stderr, exitCode] = await Promise.all([
        new Response(child.stdout).text(),
        new Response(child.stderr).text(),
        child.exited,
      ]);
      if (exitCode !== 0) {
        throw new Error(stderr || `git show exited ${exitCode}`);
      }
      return stdout;
    },
    catch: (cause) =>
      new HarnessEvaluationError({
        detail: String(cause),
        operation: "read",
        target: `${commit}:${path}`,
      }),
  });

