    manifest
  );
  yield* fileSystem.makeDirectory(dirname(outputPath), {
    recursive: true,
    mode: 0o700,
  });
  yield* fileSystem.writeFileString(outputPath, manifestText, { mode: 0o600 });
  yield* fileSystem.chmod(outputPath, 0o600);
