      );
      const encodedEnvironmentVariableId = yield* Schema.encodeEffect(
        VercelEnvironmentVariableId
      )(input.environmentVariableId).pipe(
        Effect.mapError(
          () =>
            new VercelStableEnvironmentReadError({
              operation: "resolvePreviewPhotonValue",
