      return yield* Match.value(input.stage).pipe(
        Match.when("preview", () =>
          Match.value(input.key).pipe(
            Match.when("BUNDJIL_CHANNEL_PHOTON_PROJECT_ID", () =>
              previewProjectIdConfig.pipe(Effect.map(Redacted.make))
