            Match.when("BUNDJIL_CHANNEL_PHOTON_WEBHOOK_ID", () =>
              productionWebhookIdConfig.pipe(Effect.map(Redacted.make))
            ),
            Match.when(
              "BUNDJIL_CHANNEL_PHOTON_WEBHOOK_SECRET",
              () => productionWebhookSecretConfig
