        ),
        Match.exhaustive,
        Effect.mapError(
          () =>
            new VercelStableEnvironmentReadError({
              operation: "resolvePreviewPhotonValue",
              reason: "requestFailed",
              retry: "never",
              certainty: { _tag: "Known" },
              message:
