    )
  ) {
    return yield* new InfrastructureStateReadmissionError({
      reason: "planScopeInvalid",
    });
  }
  return InfrastructureStateReadmissionPlanSummary.make({
    action: 0,
    create: 0,
    delete: 0,
    noOp: noOps.length,
    replace: 0,
    resourceCount: resources.length,
    update: updates.length,
