import { Ajv2020 } from "ajv/dist/2020.js";
import { describe, expect, it } from "vitest";

import authorityEnvelopeSchema from "../../../.agents/skills/docs-maintainer/assets/harness/authority-envelope.schema.json" with { type: "json" };
import policy from "../schemas/preview-state-readmission-authority.schema.json" with { type: "json" };

const authority = {
  schemaVersion: "1",
  principal: "Cooper",
  identitySource: "Cooper personal provider sessions",
  localWrite: true,
  externalAccess: "mutation",
  operations: ["alchemy-preview-state-readmission"],
  resources: [
    "alchemy:BundjilInfrastructure:preview",
    "r2:bundjil-alchemy-state:bundjil/v1",
    "vercel:bundjil-agent:read-only",
    "vercel:bundjil-codex-proxy:read-only",
    "photon:bundjil-preview:read-only",
  ],
  environments: ["preview"],
  duration: "one exact operation",
  revocation: "stop before another plan or apply",
  approvalRequired: true,
  approvalReceipt: "approved goal in Codex task",
  stopConditions: ["any plan outside the exact approved updates"],
  readback: ["following Alchemy plan must be unchanged"],
  rollback: ["stop and restore the prior accepted manifest under new authority"],
  escalation: "Cooper",
};

describe("Preview state re-admission authority", () => {
  const options = { allErrors: true, strict: false } as const;
  const envelope = new Ajv2020(options).compile(authorityEnvelopeSchema);
  const validate = new Ajv2020(options).compile(policy);

  it("accepts only the fixed Preview state-only operation", () => {
    expect(envelope(authority)).toBe(true);
    expect(validate(authority)).toBe(true);
    expect(validate({ ...authority, environments: ["prod"] })).toBe(false);
    expect(
      validate({
        ...authority,
        operations: ["alchemy-preview-state-readmission", "vercel-update"],
      })
    ).toBe(false);
    expect(
      validate({
        ...authority,
        resources: [...authority.resources, "vercel:all-projects"],
      })
    ).toBe(false);
  });
});

import { assert, it } from "@effect/vitest";
import { Effect, Exit, Schema } from "effect";

import {
  AdoptionManifest,
  validateInfrastructureStateReadmissionConvergence,
  validateInfrastructureStateReadmissionPlan,
} from "../src/index.js";

const digest =
  "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
const manifest = Schema.decodeUnknownSync(AdoptionManifest)({
  schemaVersion: "1",
  stage: "preview",
  digest,
  resources: Array.from({ length: 155 }, (_, index) => ({
    provider: "vercel",
    resourceKind: "vercelEnvironmentVariable",
    owner: { _tag: "VercelTeam", teamId: "team_preview" },
    physicalId: {
      teamId: "team_preview",
      projectId: "prj_preview",
      environmentVariableId: `env_${index}`,
    },
    desired: {
      key: `BUNDJIL_TEST_${index}`,
      type: "sensitive",
      targets: ["preview"],
      valueOwnership: { _tag: "ObservedUnknown", configured: true },
    },
    stage: "preview",
    logicalId: `vercel-environment:prj_preview:env_${index}`,
    removalPolicy: "retain",
    observedMetadataDigest: digest,
  })),
});
const approvedIds = manifest.resources
  .slice(0, 8)
  .map((resource) => resource.logicalId);

const makePlan = (updates: ReadonlyArray<string>) => ({
  resources: Object.fromEntries(
    manifest.resources.map((resource, index) => [
      `resource-${index}`,
      {
        action: updates.includes(resource.logicalId) ? "update" : "noop",
        resource: {
          LogicalId: resource.logicalId,
          Type: "Bundjil.Infrastructure.VercelEnvironmentVariable",
        },
      },
    ])
  ),
  actions: {},
  deletions: {},
  actionDeletions: {},
});

it.effect("accepts only the exact eight state refresh updates", () =>
  Effect.gen(function* () {
    const summary = yield* validateInfrastructureStateReadmissionPlan(
      manifest,
      approvedIds,
      makePlan(approvedIds)
    );
    assert.deepStrictEqual(summary, {
      action: 0,
      create: 0,
      delete: 0,
      noOp: 147,
      replace: 0,
      resourceCount: 155,
      update: 8,
    });
    const convergence = yield* validateInfrastructureStateReadmissionConvergence(
      makePlan([])
    );
    assert.strictEqual(convergence.noOp, 155);
  })
);

it.effect("fails closed when the plan updates an unapproved identity", () =>
  Effect.gen(function* () {
    const wrongIds = [...approvedIds.slice(0, 7), manifest.resources[8]!.logicalId];
    const exit = yield* Effect.exit(
      validateInfrastructureStateReadmissionPlan(
        manifest,
        approvedIds,
        makePlan(wrongIds)
      )
    );
    assert.strictEqual(Exit.isFailure(exit), true);
  })
);

