      ...withPath,
      ...Option.match(manifestDigest, {
        onNone: () => ({}),
        onSome: (digest) => ({ manifestDigest: digest }),
      }),
    });
  }
).pipe(Effect.withSpan("InfrastructureCommandConfig.load"));

