      ),
      duration: { _tag: "NotExposed" },
      ownership,
      providerRead: resource.action === "skipped" ? "skipped" : "performed",
      readback: "available",
      resourceFingerprint: InfrastructureDriftResourceFingerprint.make(
        sha256(resource.fqn)
