import { AlchemyContextLive } from "alchemy/AlchemyContext";
import { ArtifactStore, createArtifactStore } from "alchemy/Artifacts";
import { selectCli } from "alchemy/Cli/selectCli";
import * as AlchemyPlan from "alchemy/Plan";
import * as AlchemyStack from "alchemy/Stack";
import { State } from "alchemy/State";
import { PlatformServices } from "alchemy/Util/PlatformServices";
import { ConfigProvider, Console, Effect, Layer, Schema } from "effect";
import * as FetchHttpClient from "effect/unstable/http/FetchHttpClient";

import { makeStableInfrastructureReadmissionStack } from "../../alchemy.stable.run.js";
import {
  InfrastructureStateReadmissionPlan,
  layerAlchemyR2State,
  loadAdoptionCommand,
  validateStableAdoptionCommand,
} from "../../packages/infrastructure/src/index.js";

const stateLayer = layerAlchemyR2State.pipe(Layer.orDie);

const runtime = Layer.mergeAll(
  PlatformServices,
  FetchHttpClient.layer,
  Layer.provideMerge(AlchemyContextLive, PlatformServices),
  Layer.succeed(ArtifactStore, createArtifactStore()),
  selectCli(),
  stateLayer,
  ConfigProvider.layer(ConfigProvider.fromEnv())
);

const program = loadAdoptionCommand.pipe(
  Effect.flatMap(validateStableAdoptionCommand),
  Effect.flatMap((manifest) =>
    AlchemyStack.evalStack(
      makeStableInfrastructureReadmissionStack(manifest),
      (stack) => AlchemyPlan.make(stack),
      { stage: "preview" }
    )
  ),
  Effect.flatMap(
    Schema.decodeUnknownEffect(InfrastructureStateReadmissionPlan)
  ),
  Effect.map((plan) => {
    const resources = Object.values(plan.resources);
    return {
      status: "passed" as const,
      counts: {
        action: Object.keys(plan.actions).length,
        create: resources.filter(({ action }) => action === "create").length,
        delete: Object.keys(plan.deletions).length,
        noOp: resources.filter(({ action }) => action === "noop").length,
        replace: resources.filter(({ action }) => action === "replace").length,
        resource: resources.length,
        update: resources.filter(({ action }) => action === "update").length,
      },
      updatedLogicalIds: resources
        .filter(({ action }) => action === "update")
        .map(({ resource }) => resource.LogicalId)
        .toSorted(),
    };
  }),
  Effect.flatMap((summary) => Console.log(JSON.stringify(summary))),
  Effect.catch(() => Console.error('{"status":"blocked"}')),
  Effect.provide(runtime)
);

await Effect.runPromise(program);
