import { createHash } from "node:crypto";

import { AlchemyContextLive } from "alchemy/AlchemyContext";
import { ArtifactStore, createArtifactStore } from "alchemy/Artifacts";
import { selectCli } from "alchemy/Cli/selectCli";
import * as AlchemyStack from "alchemy/Stack";
import * as AlchemySync from "alchemy/Sync";
import { PlatformServices } from "alchemy/Util/PlatformServices";
import { ConfigProvider, Console, Effect, Layer, Record, Schema } from "effect";
import * as FetchHttpClient from "effect/unstable/http/FetchHttpClient";

import { makeStableInfrastructureDriftStack } from "../../alchemy.stable.run.js";
import {
  layerAlchemyR2State,
  loadAdoptionCommand,
  validateStableAdoptionCommand,
} from "../../packages/infrastructure/src/index.js";

const NativeResource = Schema.Struct({
  action: Schema.Literals(["unchanged", "drifted", "missing", "skipped"]),
  fqn: Schema.NonEmptyString,
  logicalId: Schema.NonEmptyString,
  resourceType: Schema.NonEmptyString,
});

const NativeResult = Schema.Struct({
  resources: Schema.Record(Schema.String, NativeResource),
});

const runtime = Layer.mergeAll(
  PlatformServices,
  FetchHttpClient.layer,
  Layer.provideMerge(AlchemyContextLive, PlatformServices),
  Layer.succeed(ArtifactStore, createArtifactStore()),
  selectCli(),
  layerAlchemyR2State.pipe(Layer.orDie),
  ConfigProvider.layer(ConfigProvider.fromEnv())
);

const program = loadAdoptionCommand.pipe(
  Effect.flatMap(validateStableAdoptionCommand),
  Effect.flatMap((manifest) =>
    AlchemyStack.evalStack(
      makeStableInfrastructureDriftStack(manifest),
      (stack) =>
        AlchemySync.plan({ name: stack.name, stage: stack.stage }).pipe(
          Effect.flatMap((native) =>
            Schema.decodeUnknownEffect(NativeResult)(native.result)
          )
        ),
      { stage: "preview" }
    )
  ),
  Effect.map((result) =>
    Record.values(result.resources)
      .filter(
        ({ resourceType }) =>
          resourceType ===
          "Bundjil.Infrastructure.VercelEnvironmentVariable"
      )
      .map(({ action, fqn, logicalId }) => ({
        action,
        fingerprint: createHash("sha256").update(fqn).digest("hex"),
        logicalId,
      }))
      .toSorted((left, right) => left.logicalId.localeCompare(right.logicalId))
  ),
  Effect.flatMap((summary) => Console.log(JSON.stringify(summary))),
  Effect.provide(runtime)
);

await Effect.runPromise(program);

