  script: string,
  environment: Record<string, string | undefined>
) => {
  const child = spawnSync(
    "bun",
    ["--conditions=@bundjil/source", "run", `scripts/${script}`],
    {
      cwd: packageRoot,
      encoding: "utf-8",
      env: {
